291	  async function buildAgentAccessState(agent: NonNullable<Awaited<ReturnType<typeof svc.getById>>>) {
292	    const membership = await access.getMembership(agent.companyId, "agent", agent.id);
293	    const grants = membership
294	      ? await access.listPrincipalGrants(agent.companyId, "agent", agent.id)
295	      : [];
296	    const hasExplicitTaskAssignGrant = grants.some((grant) => grant.permissionKey === "tasks:assign");
297	
298	    if (agent.role === "ceo") {
299	      return {
300	        canAssignTasks: true,
301	        taskAssignSource: "ceo_role" as const,
302	        membership,
303	        grants,
304	      };
305	    }
306	
307	    if (canCreateAgents(agent)) {
308	      return {
309	        canAssignTasks: true,
310	        taskAssignSource: "agent_creator" as const,
311	        membership,
312	        grants,
313	      };
314	    }
315	
316	    if (hasExplicitTaskAssignGrant) {
317	      return {
318	        canAssignTasks: true,
319	        taskAssignSource: "explicit_grant" as const,
320	        membership,
321	        grants,
322	      };
323	    }
324	
325	    return {
326	      canAssignTasks: false,
327	      taskAssignSource: "none" as const,
328	      membership,
329	      grants,
330	    };
331	  }
